<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { usePolling } from '../composables/usePolling'
import * as planApi from '../api/studyPlan'
const plans=ref([]);const selected=ref(null);const loading=ref(false);const dialog=ref(false);const saving=ref(false);const form=reactive({goal:'制定我的学习计划',startDate:new Date().toISOString().slice(0,10),endDate:new Date(Date.now()+6*86400000).toISOString().slice(0,10),dailyMinutes:30});const pollId=ref(null)
const {start:startPolling}=usePolling(async()=>{if(!pollId.value)return 'READY';const r=await planApi.getStudyPlan(pollId.value);const d=r.data.data; if(selected.value?.id===pollId.value)selected.value=d; if(d.generationStatus==='FAILED')ElMessage.error(d.errorMessage||'计划生成失败');return d.generationStatus},{interval:1500,timeout:180000,onError:()=>ElMessage.error('计划状态查询失败')})
async function load(){loading.value=true;try{const r=await planApi.listStudyPlans({page:1,pageSize:30});plans.value=r.data.data?.rows||[];if(!selected.value&&plans.value[0])await open(plans.value[0].id)}catch(e){ElMessage.error(e.response?.data?.msg||'计划加载失败')}finally{loading.value=false}}
async function open(id){try{const r=await planApi.getStudyPlan(id);selected.value=r.data.data}catch(e){ElMessage.error(e.response?.data?.msg||'计划详情加载失败')}}
async function generate(){saving.value=true;try{const r=await planApi.generateStudyPlan(form);pollId.value=r.data.data.planId;dialog.value=false;ElMessage.success('学习计划生成中');await load();await startPolling()}catch(e){ElMessage.error(e.response?.data?.msg||'生成计划失败')}finally{saving.value=false}}
async function toggle(task){try{await planApi.updateStudyPlanTask(selected.value.id,task.id,!task.completed);task.completed=!task.completed;await load()}catch(e){ElMessage.error(e.response?.data?.msg||'更新任务失败')}}
async function remove(plan){try{await ElMessageBox.confirm('确定删除此学习计划？','确认删除',{type:'warning'});await planApi.deleteStudyPlan(plan.id);if(selected.value?.id===plan.id)selected.value=null;await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.msg||'删除失败')}}
onMounted(load)
</script>
<template><div class="page"><div class="page-heading"><div><h2>AI 学习计划</h2><p>结合学习进度和薄弱知识点生成可执行的每日任务。</p></div><el-button type="primary" @click="dialog=true">生成计划</el-button></div><el-row :gutter="16"><el-col :xs="24" :md="8"><el-card><template #header>计划列表</template><el-skeleton v-if="loading" :rows="4" animated/><el-empty v-else-if="!plans.length" description="暂无计划"/><div v-else><div v-for="plan in plans" :key="plan.id" class="plan-item" :class="{active:selected?.id===plan.id}" @click="open(plan.id)"><div><strong>{{plan.title}}</strong><div class="muted">{{plan.status}} · {{plan.progress||0}}%</div></div><el-button link type="danger" @click.stop="remove(plan)">删</el-button></div></div></el-card></el-col><el-col :xs="24" :md="16"><el-card v-if="selected"><template #header><div class="detail-header"><strong>{{selected.title||'学习计划'}}</strong><el-tag :type="selected.generationStatus==='READY'?'success':'warning'">{{selected.generationStatus}}</el-tag></div></template><el-alert v-if="selected.generationStatus==='FAILED'" type="error" :title="selected.errorMessage||'生成失败'" :closable="false"/><el-empty v-else-if="!selected.tasks?.length" description="计划正在生成"/><el-timeline v-else><el-timeline-item v-for="task in selected.tasks" :key="task.id" :timestamp="`${task.date} · ${task.estimatedMinutes}分钟`" :type="task.completed?'success':'primary'"><el-checkbox :model-value="task.completed" @change="toggle(task)">{{task.topic}}（{{task.type}}）</el-checkbox><el-button v-if="!task.completed" link type="primary" @click="$router.push({path:'/pomodoro',query:{topic:task.topic}})">专注学习</el-button></el-timeline-item></el-timeline></el-card><el-empty v-else description="请选择一个计划"/></el-col></el-row><el-dialog v-model="dialog" title="生成学习计划" width="480px"><el-form label-position="top"><el-form-item label="学习目标"><el-input v-model="form.goal" type="textarea"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="form.startDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="form.endDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="每日分钟"><el-input-number v-model="form.dailyMinutes" :min="5" :max="1440"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="generate">生成</el-button></template></el-dialog></div></template>
<style scoped>.page{max-width:1200px;margin:0 auto}.page-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}h2{margin:0 0 6px}p,.muted{color:#909399;margin:0;font-size:13px}.plan-item{display:flex;justify-content:space-between;align-items:center;padding:12px 8px;border-bottom:1px solid #ebeef5;cursor:pointer}.plan-item.active{background:#ecf5ff}.detail-header{display:flex;justify-content:space-between}@media(max-width:600px){.page-heading{align-items:flex-start;flex-direction:column;gap:12px}}</style>
